package dev.thefoolish.generated.anishelf;
import android.widget.*;import java.util.*;
public final class ProvidersActivity extends AppScreen{protected void render(){title("Extensions");subtitle("Installed sources are available immediately. Add repositories only when you want more compatible sources.");section("Built in");List<MediaProvider> built=BuiltInProviderCatalog.providers();if(built.isEmpty())body.addView(card("No built-in sources","AIDao could not safely bundle a compatible source for this project."));for(MediaProvider p:built){body.addView(card(p.displayName()+" · Enabled",p.health()+"\n"+BuiltInProviderCatalog.provenance()));}section("Repository extensions");List<ExtensionRecord> known=new ExtensionManager(this).known();if(known.isEmpty()){body.addView(card("No additional extensions","The app is still usable with its built-in source. Add a compatible HTTPS repository to discover more providers."));}for(ExtensionRecord x:known){boolean compatible=x.searchable();String capability=(compatible?"Search: compatible":"Unsupported repository metadata")+" · "+(x.playable()?"Playback: compatible":"Playback: unavailable");LinearLayout c=card(x.name+" · "+x.state,x.version+" · "+x.repoUrl+"\n"+capability);Button toggle=button(!compatible?"Unsupported repository metadata":x.state==ExtensionRecord.State.ENABLED?"Disable extension":"Enable extension");toggle.setMinHeight(dp(52));toggle.setContentDescription(toggle.getText());toggle.setEnabled(compatible);if(compatible)toggle.setOnClickListener(v->{ExtensionRecord.State next=x.state==ExtensionRecord.State.ENABLED?ExtensionRecord.State.DISABLED:ExtensionRecord.State.ENABLED;new ExtensionManager(this).setState(x.id,next);recreate();});c.addView(toggle);if(!compatible)c.addView(text("AIDao cannot execute arbitrary extension APKs. This entry remains visible for provenance until it declares a compatible HTTPS search contract.",13,false));body.addView(c);}Button repos=button("Manage repositories");repos.setOnClickListener(v->AppNavigator.open(this,RepositoriesActivity.class));body.addView(repos);}}
